CREATE OR REPLACE FUNCTION _migrate_single_pokemon(
  p_poke JSONB,
  p_ability_map JSONB,
  p_nature_map JSONB,
  p_item_map JSONB,
  p_move_map JSONB
) RETURNS JSONB AS $$
DECLARE
  v_poke JSONB := p_poke;
  v_species TEXT;
  v_id TEXT;
  v_ability TEXT;
  v_nature TEXT;
  v_item TEXT;
  v_norm TEXT;
  v_moves JSONB;
  v_new_moves JSONB;
  v_move JSONB;
  v_move_id TEXT;
  v_move_name TEXT;
BEGIN
  IF v_poke IS NULL OR jsonb_typeof(v_poke) != 'object' THEN
    RETURN v_poke;
  END IF;

  -- 0. Species and ID normalization (nidoran_m -> nidoranm, nidoran_f -> nidoranf, mr_mime -> mrmime)
  v_species := coalesce(v_poke ->> 'species', v_poke ->> 'id', '');
  v_id := coalesce(v_poke ->> 'id', v_poke ->> 'species', '');
  IF NOT (v_poke ? 'species') OR (v_poke ->> 'species') IS NULL THEN
    v_poke := jsonb_set(v_poke, '{species}', to_jsonb(v_species));
  END IF;
  IF v_species = 'nidoran_m' OR v_id = 'nidoran_m' THEN
    IF v_species IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{species}', '"nidoranm"'::jsonb); END IF;
    IF v_id IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{id}', '"nidoranm"'::jsonb); END IF;
  ELSIF v_species = 'nidoran_f' OR v_id = 'nidoran_f' THEN
    IF v_species IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{species}', '"nidoranf"'::jsonb); END IF;
    IF v_id IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{id}', '"nidoranf"'::jsonb); END IF;
  ELSIF v_species = 'mr_mime' OR v_id = 'mr_mime' THEN
    IF v_species IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{species}', '"mrmime"'::jsonb); END IF;
    IF v_id IS NOT NULL THEN v_poke := jsonb_set(v_poke, '{id}', '"mrmime"'::jsonb); END IF;
  END IF;

  -- 1. Ability
  v_ability := v_poke ->> 'ability';
  IF v_ability IS NOT NULL AND v_ability != '' THEN
    v_norm := regexp_replace(translate(lower(v_ability), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
    IF p_ability_map ->> v_norm IS NOT NULL THEN
      v_poke := jsonb_set(v_poke, '{ability}', to_jsonb(p_ability_map ->> v_norm));
    ELSIF p_ability_map ->> lower(v_ability) IS NOT NULL THEN
      v_poke := jsonb_set(v_poke, '{ability}', to_jsonb(p_ability_map ->> lower(v_ability)));
    END IF;
  END IF;

  -- Special fix for Psyduck and early access illegal abilities in commerce tables
  IF v_species = 'psyduck' AND (v_ability IN ('obstruir', 'Obstruir', 'soundproof', 'insonorizar', 'Insonorizar') OR (v_poke ->> 'ability') IN ('obstruir', 'Obstruir', 'soundproof', 'insonorizar', 'Insonorizar')) THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"damp"'::jsonb);
  ELSIF v_species = 'togepi' AND (v_ability = 'overgrow' OR (v_poke ->> 'ability') = 'overgrow') THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"serenegrace"'::jsonb);
  ELSIF v_species = 'haunter' AND (v_ability = 'overgrow' OR (v_poke ->> 'ability') = 'overgrow') THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"levitate"'::jsonb);
  ELSIF v_species = 'kadabra' AND (v_ability = 'overgrow' OR (v_poke ->> 'ability') = 'overgrow') THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"synchronize"'::jsonb);
  ELSIF v_species = 'gengar' AND ((v_ability IN ('levitate', 'overgrow')) OR ((v_poke ->> 'ability') IN ('levitate', 'overgrow'))) THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"cursedbody"'::jsonb);
  ELSIF v_species = 'cleffa' AND (v_ability = 'naturalcure' OR (v_poke ->> 'ability') = 'naturalcure') THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"cutecharm"'::jsonb);
  ELSIF v_species IN ('geodude', 'graveler', 'golem') AND (v_ability IN ('unnerve', 'nerviosismo', 'Nerviosismo') OR (v_poke ->> 'ability') IN ('unnerve', 'nerviosismo', 'Nerviosismo')) THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"rockhead"'::jsonb);
  ELSIF v_species = 'vileplume' AND (v_ability = 'overgrow' OR (v_poke ->> 'ability') = 'overgrow') THEN
    v_poke := jsonb_set(v_poke, '{ability}', '"chlorophyll"'::jsonb);
  END IF;

  -- 2. Nature
  v_nature := v_poke ->> 'nature';
  IF v_nature IS NOT NULL AND v_nature != '' THEN
    v_norm := regexp_replace(translate(lower(v_nature), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
    IF p_nature_map ->> v_norm IS NOT NULL THEN
      v_poke := jsonb_set(v_poke, '{nature}', to_jsonb(p_nature_map ->> v_norm));
    ELSIF p_nature_map ->> lower(v_nature) IS NOT NULL THEN
      v_poke := jsonb_set(v_poke, '{nature}', to_jsonb(p_nature_map ->> lower(v_nature)));
    END IF;
  END IF;

  -- 3. Held Item
  v_item := v_poke ->> 'heldItem';
  IF v_item IS NOT NULL AND v_item != '' THEN
    v_norm := regexp_replace(translate(lower(v_item), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
    IF p_item_map ->> v_norm IS NOT NULL THEN
      v_poke := jsonb_set(v_poke, '{heldItem}', to_jsonb(p_item_map ->> v_norm));
    ELSIF p_item_map ->> lower(v_item) IS NOT NULL THEN
      v_poke := jsonb_set(v_poke, '{heldItem}', to_jsonb(p_item_map ->> lower(v_item)));
    END IF;
  END IF;

  -- 4. Moves
  v_moves := v_poke -> 'moves';
  IF v_moves IS NOT NULL AND jsonb_typeof(v_moves) = 'array' THEN
    v_new_moves := '[]'::jsonb;
    FOR v_move IN SELECT * FROM jsonb_array_elements(v_moves) LOOP
      v_move_id := v_move ->> 'id';
      v_move_name := v_move ->> 'name';
      v_norm := regexp_replace(translate(lower(coalesce(v_move_id, v_move_name, '')), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
      IF p_move_map ->> v_norm IS NOT NULL THEN
        v_move := jsonb_set(v_move, '{id}', to_jsonb(p_move_map ->> v_norm));
      END IF;
      v_new_moves := v_new_moves || v_move;
    END LOOP;
    v_poke := jsonb_set(v_poke, '{moves}', v_new_moves);
  END IF;

  -- 4b. Legalize early access illegal moves in legacy saves & commerce tables
  IF v_species IN ('vulpix', 'haunter', 'gengar') THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"confusion"', '"id":"confuseray"'), '"id": "confusion"', '"id":"confuseray"')::jsonb);
  ELSIF v_species = 'starmie' THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"quickattack"', '"id":"swift"'), '"id": "quickattack"', '"id":"swift"')::jsonb);
  ELSIF v_species IN ('graveler', 'golem') THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"lockon"', '"id":"defensecurl"'), '"id": "lockon"', '"id":"defensecurl"')::jsonb);
  ELSIF v_species = 'venonat' THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"poisonsting"', '"id":"poisonpowder"'), '"id": "poisonsting"', '"id":"poisonpowder"')::jsonb);
  ELSIF v_species = 'snorlax' THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"thrash"', '"id":"bodyslam"'), '"id": "thrash"', '"id":"bodyslam"')::jsonb);
  ELSIF v_species = 'chansey' THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"harden"', '"id":"defensecurl"'), '"id": "harden"', '"id":"defensecurl"')::jsonb);
  ELSIF v_species = 'poliwhirl' THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"stomp"', '"id":"bodyslam"'), '"id": "stomp"', '"id":"bodyslam"')::jsonb);
  ELSIF v_species = 'venomoth' THEN
    v_poke := jsonb_set(v_poke, '{moves}', replace(replace((v_poke -> 'moves')::text, '"id":"wingattack"', '"id":"gust"'), '"id": "wingattack"', '"id":"gust"')::jsonb);
  END IF;

  -- 4c. Ensure mandatory hp and uid for passive teams and commerce entities
  IF NOT (v_poke ? 'hp') OR (v_poke ->> 'hp') IS NULL THEN
    v_poke := jsonb_set(v_poke, '{hp}', coalesce(v_poke -> 'maxHp', '100'::jsonb));
  END IF;
  IF NOT (v_poke ? 'uid') OR (v_poke ->> 'uid') IS NULL OR (v_poke ->> 'uid') = '' THEN
    v_poke := jsonb_set(v_poke, '{uid}', to_jsonb('passive-' || coalesce(v_poke ->> 'id', 'pokemon')));
  END IF;

  -- 5. Vigor and maxVigor normalization
  v_species := coalesce(v_poke ->> 'species', v_poke ->> 'id', '');
  IF v_species IN ('articuno', 'zapdos', 'moltres', 'mewtwo', 'mew', 'omanyte', 'omastar', 'kabuto', 'kabutops', 'aerodactyl') THEN
    v_poke := jsonb_set(v_poke, '{maxVigor}', '0'::jsonb);
    v_poke := jsonb_set(v_poke, '{vigor}', '0'::jsonb);
  ELSE
    IF NOT (v_poke ? 'maxVigor') OR (v_poke ->> 'maxVigor') IS NULL THEN
      DECLARE
        v_curr_vigor INT := COALESCE((v_poke ->> 'vigor')::int, 3);
      BEGIN
        IF v_curr_vigor < 1 THEN v_curr_vigor := 3; END IF;
        v_poke := jsonb_set(v_poke, '{maxVigor}', to_jsonb(v_curr_vigor));
        IF NOT (v_poke ? 'vigor') OR (v_poke ->> 'vigor') IS NULL THEN
          v_poke := jsonb_set(v_poke, '{vigor}', to_jsonb(v_curr_vigor));
        END IF;
      END;
    END IF;
    IF NOT (v_poke ? 'vigor') OR (v_poke ->> 'vigor') IS NULL THEN
      v_poke := jsonb_set(v_poke, '{vigor}', coalesce(v_poke -> 'maxVigor', '3'::jsonb));
    END IF;
  END IF;

  -- 6. Legalize corrected abilities
  IF (v_poke ->> 'isIllegal')::boolean IS TRUE THEN
    IF (v_poke ->> 'ability') = 'runaway' THEN
      v_poke := jsonb_set(v_poke, '{isIllegal}', 'false'::jsonb);
      v_poke := jsonb_set(v_poke, '{illegalReasons}', '[]'::jsonb);
    END IF;
  END IF;

  RETURN v_poke;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION _migrate_pokemon_array(
  p_arr JSONB,
  p_ability_map JSONB,
  p_nature_map JSONB,
  p_item_map JSONB,
  p_move_map JSONB
) RETURNS JSONB AS $$
DECLARE
  v_res JSONB := '[]'::jsonb;
  v_item JSONB;
  v_moves_birth JSONB;
  v_new_mb JSONB;
  v_m TEXT;
  v_norm_m TEXT;
BEGIN
  IF p_arr IS NULL OR jsonb_typeof(p_arr) != 'array' THEN
    RETURN p_arr;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_arr) LOOP
    IF v_item IS NOT NULL AND jsonb_typeof(v_item) = 'object' THEN
      IF (v_item ->> 'isEgg')::boolean IS TRUE OR v_item ? 'steps' OR v_item ? 'movesAtBirth' THEN
        -- Egg normalization
        IF v_item ? 'nature' AND (v_item ->> 'nature') IS NOT NULL THEN
          DECLARE
            v_nat TEXT := v_item ->> 'nature';
            v_norm TEXT := regexp_replace(translate(lower(v_nat), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
          BEGIN
            IF p_nature_map ->> v_norm IS NOT NULL THEN
              v_item := jsonb_set(v_item, '{nature}', to_jsonb(p_nature_map ->> v_norm));
            END IF;
          END;
        END IF;
        v_moves_birth := v_item -> 'movesAtBirth';
        IF v_moves_birth IS NOT NULL AND jsonb_typeof(v_moves_birth) = 'array' THEN
          v_new_mb := '[]'::jsonb;
          FOR v_m IN SELECT jsonb_array_elements_text(v_moves_birth) LOOP
            v_norm_m := regexp_replace(translate(lower(v_m), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
            IF p_move_map ->> v_norm_m IS NOT NULL THEN
              v_new_mb := v_new_mb || to_jsonb(p_move_map ->> v_norm_m);
            ELSE
              v_new_mb := v_new_mb || to_jsonb(v_m);
            END IF;
          END LOOP;
          v_item := jsonb_set(v_item, '{movesAtBirth}', v_new_mb);
        END IF;
        v_res := v_res || v_item;
      ELSE
        v_res := v_res || _migrate_single_pokemon(v_item, p_ability_map, p_nature_map, p_item_map, p_move_map);
      END IF;
    ELSE
      v_res := v_res || v_item;
    END IF;
  END LOOP;

  RETURN v_res;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION _migrate_inventory(
  p_inv JSONB,
  p_item_map JSONB
) RETURNS JSONB AS $$
DECLARE
  v_new_inv JSONB := '{}'::jsonb;
  v_key TEXT;
  v_qty JSONB;
  v_target_key TEXT;
  v_norm TEXT;
  v_existing_qty INT;
BEGIN
  IF p_inv IS NULL OR jsonb_typeof(p_inv) != 'object' THEN
    RETURN p_inv;
  END IF;

  FOR v_key, v_qty IN SELECT * FROM jsonb_each(p_inv) LOOP
    v_norm := regexp_replace(translate(lower(v_key), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
    IF p_item_map ->> v_norm IS NOT NULL THEN
      v_target_key := p_item_map ->> v_norm;
    ELSIF p_item_map ->> lower(v_key) IS NOT NULL THEN
      v_target_key := p_item_map ->> lower(v_key);
    ELSIF p_item_map ->> v_key IS NOT NULL THEN
      v_target_key := p_item_map ->> v_key;
    ELSE
      v_target_key := v_key;
    END IF;

    v_existing_qty := COALESCE((v_new_inv ->> v_target_key)::int, 0);
    v_new_inv := jsonb_set(v_new_inv, ARRAY[v_target_key], to_jsonb(v_existing_qty + (v_qty::text)::int));
  END LOOP;

  RETURN v_new_inv;
END;
$$ LANGUAGE plpgsql;

DO $$
DECLARE
  v_ability_map JSONB := '{"adaptable":"adaptability","adaptability":"adaptability","bucleaire":"cloudnine","airlock":"airlock","trampaarena":"arenatrap","arenatrap":"arenatrap","armadurabatalla":"battlearmor","battlearmor":"battlearmor","sacapecho":"bigpecks","bigpecks":"bigpecks","marllamas":"blaze","blaze":"blaze","clorofila":"chlorophyll","chlorophyll":"chlorophyll","cuerpopuro":"clearbody","clearbody":"clearbody","cloudnine":"cloudnine","cambiocolor":"colorchange","colorchange":"colorchange","ojocompuesto":"compoundeyes","compoundeyes":"compoundeyes","granencanto":"cutecharm","cutecharm":"cutecharm","humedad":"damp","damp":"damp","llovizna":"drizzle","drizzle":"drizzle","sequia":"drought","drought":"drought","madrugar":"earlybird","earlybird":"earlybird","efectoespora":"effectspore","effectspore":"effectspore","cuerpollama":"flamebody","flamebody":"flamebody","absorbefuego":"flashfire","flashfire":"flashfire","prediccion":"forewarn","forecast":"forecast","agallas":"guts","guts":"guts","potencia":"hugepower","hugepower":"hugepower","entusiasmo":"hustle","hustle":"hustle","cortefuerte":"hypercutter","hypercutter":"hypercutter","iluminacion":"illuminate","illuminate":"illuminate","inmunidad":"immunity","immunity":"immunity","allanamiento":"infiltrator","infiltrator":"infiltrator","focointerno":"innerfocus","innerfocus":"innerfocus","insomnio":"insomnia","insomnia":"insomnia","intimidacion":"intimidate","intimidate":"intimidate","vistalince":"keeneye","keeneye":"keeneye","levitacion":"levitate","levitate":"levitate","pararrayos":"lightningrod","lightningrod":"lightningrod","flexibilidad":"limber","limber":"limber","viscosidad":"stickyhold","liquidooze":"liquidooze","escudomagma":"magmaarmor","magmaarmor":"magmaarmor","iman":"magnetpull","magnetpull":"magnetpull","escamaespecial":"marvelscale","marvelscale":"marvelscale","menos":"minus","minus":"minus","curanatural":"naturalcure","naturalcure":"naturalcure","despiste":"oblivious","oblivious":"oblivious","espesura":"overgrow","overgrow":"overgrow","owntempo":"owntempo","recogida":"pickup","pickup":"pickup","mas":"plus","plus":"plus","puntotoxico":"poisonpoint","poisonpoint":"poisonpoint","presion":"pressure","pressure":"pressure","energiapura":"purepower","purepower":"purepower","curalluvia":"raindish","raindish":"raindish","rivalidad":"rivalry","rivalry":"rivalry","cabezaroca":"rockhead","rockhead":"rockhead","pieltosca":"roughskin","roughskin":"roughskin","fuga":"runaway","runaway":"runaway","impetuarena":"sandrush","sandrush":"sandrush","chorroarena":"sandstream","sandstream":"sandstream","veloarena":"sandveil","sandveil":"sandveil","dicha":"serenegrace","serenegrace":"serenegrace","sombratrampa":"shadowtag","shadowtag":"shadowtag","mudar":"shedskin","shedskin":"shedskin","caparazon":"shellarmor","shellarmor":"shellarmor","polvoescudo":"shielddust","shielddust":"shielddust","francotirador":"sniper","sniper":"sniper","podersolar":"solarpower","solarpower":"solarpower","insonorizar":"soundproof","soundproof":"soundproof","impulso":"speedboost","speedboost":"speedboost","electricidadestatica":"static","static":"static","hedor":"stench","stench":"stench","stickyhold":"stickyhold","robustez":"sturdy","sturdy":"sturdy","ventosas":"suctioncups","suctioncups":"suctioncups","enjambre":"swarm","swarm":"swarm","nadorapido":"swiftswim","swiftswim":"swiftswim","sincronia":"synchronize","synchronize":"synchronize","tumbos":"tangledfeet","tangledfeet":"tangledfeet","sebo":"thickfat","thickfat":"thickfat","cromolente":"tintedlens","tintedlens":"tintedlens","torrente":"torrent","torrent":"torrent","rastro":"trace","trace":"trace","ausente":"truant","truant":"truant","tension":"unnerve","unnerve":"unnerve","alboroto":"soundproof","uproar":"uproar","espirituvital":"vitalspirit","vitalspirit":"vitalspirit","absorbeelectricidad":"voltabsorb","voltabsorb":"voltabsorb","absorbeagua":"waterabsorb","waterabsorb":"waterabsorb","veloagua":"waterveil","waterveil":"waterveil","humoblanco":"whitesmoke","