afin":"tailwind","tailwind":"tailwind","takeheart":"takeheart","alquitranazo":"tarshot","tarshot":"tarshot","ojosllorosos":"tearfullook","tearfullook":"tearfullook","horadelte":"teatime","teatime":"teatime","tecnoshock":"technoblast","technoblast":"technoblast","barrenatelurica":"tectonicrage","tectonicrage":"tectonicrage","telequinesis":"telekinesis","telekinesis":"telekinesis","coleraardiente":"temperflare","temperflare":"temperflare","terablast":"terablast","teracluster":"terastarstorm","terastarstorm":"terastarstorm","pulsodecampo":"terrainpulse","terrainpulse":"terrainpulse","milflechas":"thousandarrows","thousandarrows":"thousandarrows","miltemblores":"thousandwaves","thousandwaves":"thousandwaves","golpemordaza":"throatchop","throatchop":"throatchop","electrojaula":"thundercage","thundercage":"thundercage","relampagosubito":"thunderclap","thunderclap":"thunderclap","colmillorayo":"thunderfang","thunderfang":"thunderfang","patadarelampago":"thunderouskick","thunderouskick":"thunderouskick","tidyup":"tidyup","reversion":"topsyturvy","topsyturvy":"topsyturvy","torchsong":"torchsong","puastoxicas":"toxicspikes","toxicspikes":"toxicspikes","hilovenenoso":"toxicthread","toxicthread":"toxicthread","trailblaze":"trailblaze","halloween":"trickortreat","trickortreat":"trickortreat","espacioraro":"trickroom","trickroom":"trickroom","triplearrows":"triplearrows","tripleaxel":"tripleaxel","tripledive":"tripledive","patadatropical":"tropkick","tropkick":"tropkick","asoculto":"trumpcard","trumpcard":"trumpcard","twinbeam":"twinbeam","arrumacosideral":"twinkletackle","twinkletackle":"twinkletackle","palmarauda":"upperhand","upperhand":"upperhand","idayvuelta":"uturn","uturn":"uturn","ondavacio":"vacuumwave","vacuumwave":"vacuumwave","vdefuego":"vcreate","vcreate":"vcreate","eevimpacto":"veeveevolley","veeveevolley":"veeveevolley","trampavenenosa":"venomdrench","venomdrench":"venomdrench","cargatoxica":"venoshock","venoshock":"venoshock","victorydance":"victorydance","voltiocambio":"voltswitch","voltswitch":"voltswitch","espabila":"wakeupslap","wakeupslap":"wakeupslap","votoagua":"waterpledge","waterpledge":"waterpledge","shurikendeagua":"watershuriken","watershuriken":"watershuriken","wavecrash":"wavecrash","golpeoscuro":"wickedblow","wickedblow":"wickedblow","wickedtorque":"wickedtorque","vastaguardia":"wideguard","wideguard":"wideguard","wildboltstorm":"wildboltstorm","voltiocruel":"wildcharge","wildcharge":"wildcharge","zonaextrana":"wonderroom","wonderroom":"wonderroom","mazazo":"woodhammer","woodhammer":"woodhammer","avivar":"workup","workup":"workup","abatidoras":"worryseed","worryseed":"worryseed","estrujon":"wringout","wringout":"wringout","tijerax":"xscissor","xscissor":"xscissor","cabezazozen":"zenheadbutt","zenheadbutt":"zenheadbutt","electropunzada":"zingzap","zingzap":"zingzap","pikaturbo":"zippyzap","zippyzap":"zippyzap","paleowave":"paleowave","shadowstrike":"shadowstrike","polarflare":"polarflare","recargando":"recharge","recharge":"recharge","arena":"sandattack","envolver":"wrap","golpekaratazo":"karatechop","movsismico":"seismictoss","portazo":"slam","acidificacion":"acidarmor","punolodo":"mudslap","mudpunch":"mudslap","prevision":"foresight","psicocontrol":"psychup","huesorus":"bonerush","huesumerang":"bonemerang","seguimiento":"pursuit","cola":"tailwhip","huevobomba":"eggbomb","desenrrollar":"rollout"}'::jsonb;
  r RECORD;
  v_save JSONB;
  v_slots JSONB;
  v_new_slots JSONB;
  v_slot JSONB;
  v_poke JSONB;
  v_asset JSONB;
  v_team JSONB;
  v_data JSONB;
BEGIN
  -- 1. Migrate game_saves
  FOR r IN SELECT user_id, save_data FROM game_saves LOOP
    v_save := r.save_data;
    IF v_save IS NOT NULL AND jsonb_typeof(v_save) = 'object' THEN
      -- team
      IF v_save ? 'team' THEN
        v_save := jsonb_set(v_save, '{team}', _migrate_pokemon_array(v_save -> 'team', v_ability_map, v_nature_map, v_item_map, v_move_map));
      END IF;
      -- box
      IF v_save ? 'box' THEN
        v_save := jsonb_set(v_save, '{box}', _migrate_pokemon_array(v_save -> 'box', v_ability_map, v_nature_map, v_item_map, v_move_map));
      END IF;
      -- daycareWarehouse
      IF v_save ? 'daycareWarehouse' THEN
        v_save := jsonb_set(v_save, '{daycareWarehouse}', _migrate_pokemon_array(v_save -> 'daycareWarehouse', v_ability_map, v_nature_map, v_item_map, v_move_map));
      END IF;
      -- daycare_slots
      IF v_save ? 'daycare_slots' AND jsonb_typeof(v_save -> 'daycare_slots') = 'array' THEN
        v_slots := v_save -> 'daycare_slots';
        v_new_slots := '[]'::jsonb;
        FOR v_slot IN SELECT * FROM jsonb_array_elements(v_slots) LOOP
          IF v_slot ? 'pokemon' AND (v_slot -> 'pokemon') IS NOT NULL THEN
            v_poke := _migrate_single_pokemon(v_slot -> 'pokemon', v_ability_map, v_nature_map, v_item_map, v_move_map);
            v_slot := jsonb_set(v_slot, '{pokemon}', v_poke);
          END IF;
          v_new_slots := v_new_slots || v_slot;
        END LOOP;
        v_save := jsonb_set(v_save, '{daycare_slots}', v_new_slots);
      END IF;
      -- inventory
      IF v_save ? 'inventory' THEN
        v_save := jsonb_set(v_save, '{inventory}', _migrate_inventory(v_save -> 'inventory', v_item_map));
      END IF;

      UPDATE game_saves SET save_data = v_save WHERE user_id = r.user_id;
    END IF;
  END LOOP;

  -- 2. Migrate trade_offers
  FOR r IN SELECT id, offer_pokemon, request_pokemon, offer_items, request_items FROM trade_offers LOOP
    IF r.offer_pokemon IS NOT NULL THEN
      UPDATE trade_offers
      SET offer_pokemon = _migrate_single_pokemon(r.offer_pokemon, v_ability_map, v_nature_map, v_item_map, v_move_map)
      WHERE id = r.id;
    END IF;
    IF r.request_pokemon IS NOT NULL THEN
      UPDATE trade_offers
      SET request_pokemon = _migrate_single_pokemon(r.request_pokemon, v_ability_map, v_nature_map, v_item_map, v_move_map)
      WHERE id = r.id;
    END IF;
    IF r.offer_items IS NOT NULL AND jsonb_typeof(r.offer_items) = 'object' THEN
      UPDATE trade_offers
      SET offer_items = _migrate_inventory(r.offer_items, v_item_map)
      WHERE id = r.id;
    END IF;
    IF r.request_items IS NOT NULL AND jsonb_typeof(r.request_items) = 'object' THEN
      UPDATE trade_offers
      SET request_items = _migrate_inventory(r.request_items, v_item_map)
      WHERE id = r.id;
    END IF;
  END LOOP;

  -- 3. Migrate claim_queue
  FOR r IN SELECT id, asset_data FROM claim_queue LOOP
    v_asset := r.asset_data;
    IF v_asset IS NOT NULL AND jsonb_typeof(v_asset) = 'object' THEN
      IF (v_asset ->> 'type') = 'pokemon' AND v_asset ? 'data' THEN
        v_poke := _migrate_single_pokemon(v_asset -> 'data', v_ability_map, v_nature_map, v_item_map, v_move_map);
        v_asset := jsonb_set(v_asset, '{data}', v_poke);
        UPDATE claim_queue SET asset_data = v_asset WHERE id = r.id;
      ELSIF (v_asset ->> 'type') = 'item' AND v_asset ? 'data' THEN
        v_data := v_asset -> 'data';
        DECLARE
          v_raw_name TEXT := coalesce(v_data ->> 'name', v_data ->> 'id', '');
          v_norm_name TEXT := regexp_replace(translate(lower(v_raw_name), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
          v_migrated_id TEXT := coalesce(v_item_map ->> v_norm_name, v_item_map ->> lower(v_raw_name), v_item_map ->> v_raw_name);
        BEGIN
          IF v_migrated_id IS NOT NULL THEN
            v_data := jsonb_set(v_data, '{name}', to_jsonb(v_migrated_id));
            IF v_data ? 'id' THEN v_data := jsonb_set(v_data, '{id}', to_jsonb(v_migrated_id)); END IF;
            v_asset := jsonb_set(v_asset, '{data}', v_data);
            UPDATE claim_queue SET asset_data = v_asset WHERE id = r.id;
          END IF;
        END;
      END IF;
    END IF;
  END LOOP;

  -- 4. Migrate market_listings
  FOR r IN SELECT id, listing_type, data FROM market_listings LOOP
    IF r.listing_type = 'pokemon' AND r.data IS NOT NULL THEN
      v_poke := _migrate_single_pokemon(r.data, v_ability_map, v_nature_map, v_item_map, v_move_map);
      UPDATE market_listings SET data = v_poke WHERE id = r.id;
    ELSIF r.listing_type = 'item' AND r.data IS NOT NULL THEN
      v_data := r.data;
      DECLARE
        v_raw_name TEXT := coalesce(v_data ->> 'name', v_data ->> 'id', '');
        v_norm_name TEXT := regexp_replace(translate(lower(v_raw_name), 'áéíóúüñ', 'aeiouun'), '[ _.-]', '', 'g');
        v_migrated_id TEXT := coalesce(v_item_map ->> v_norm_name, v_item_map ->> lower(v_raw_name), v_item_map ->> v_raw_name);
      BEGIN
        IF v_migrated_id IS NOT NULL THEN
          v_data := jsonb_set(v_data, '{name}', to_jsonb(v_migrated_id));
          IF v_data ? 'id' THEN v_data := jsonb_set(v_data, '{id}', to_jsonb(v_migrated_id)); END IF;
          UPDATE market_listings SET data = v_data WHERE id = r.id;
        END IF;
      END;
    END IF;
  END LOOP;

  -- 5. Migrate war_defenders
  FOR r IN SELECT id, pokemon_data FROM war_defenders LOOP
    IF r.pokemon_data IS NOT NULL THEN
      v_poke := _migrate_single_pokemon(r.pokemon_data, v_ability_map, v_nature_map, v_item_map, v_move_map);
      UPDATE war_defenders SET pokemon_data = v_poke WHERE id = r.id;
    END IF;
  END LOOP;

  -- 6. Migrate passive_teams
  FOR r IN SELECT user_id, team_data FROM passive_teams LOOP
    IF r.team_data IS NOT NULL THEN
      v_team := _migrate_pokemon_array(r.team_data, v_ability_map, v_nature_map, v_item_map, v_move_map);
      UPDATE passive_teams SET team_data = v_team WHERE user_id = r.user_id;
    END IF;
  END LOOP;

  -- 7. Update system_config db_version
  INSERT INTO system_config (key, value)
  VALUES ('db_version', '20260909010000'::jsonb)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();

END $$;

DROP FUNCTION IF EXISTS _migrate_single_pokemon(JSONB, JSONB, JSONB, JSONB, JSONB);
DROP FUNCTION IF EXISTS _migrate_pokemon_array(JSONB, JSONB, JSONB, JSONB, JSONB);
DROP FUNCTION IF EXISTS _migrate_inventory(JSONB, JSONB);
